// Local Editor probe only. No runtime component is created.
using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEngine.SceneManagement;
using UnityEngine.Profiling;
using UnityEngine.Rendering;
using Unity.Profiling;
using Unity.Profiling.LowLevel.Unsafe;
using Newtonsoft.Json;
public static class LightningNovaPerformance {
 static string Out=Path.Combine(Directory.GetParent(Application.dataPath).FullName,"VFXWork/Previews/LightningNova/V1.3");
 class Phase{public int repeat,count;public string variant;public bool stagger;}
 class Row{public int phase,frame,batches,draws,setPass,particles;public double age,cpu,gpu,render,particle,gc;}
 static List<Phase> phases=new List<Phase>();static List<Row> rows=new List<Row>(20000);static List<GameObject> clones=new List<GameObject>();static List<GameObject> demos=new List<GameObject>();static List<bool> active=new List<bool>();static Dictionary<string,ProfilerRecorder> counters=new Dictionary<string,ProfilerRecorder>();static ParticleSystem[] systems;static int phase=-1,frame=-1;static double begin;static bool background;static EditorWindow focused;static object environment;
 static double Read(string name,bool ms=true){ProfilerRecorder r;return counters.TryGetValue(name,out r)&&r.Valid&&r.Count>0?r.LastValue/(ms?1000000.0:1):double.NaN;}
 static void Next(){foreach(var g in clones)if(g!=null)UnityEngine.Object.Destroy(g);clones.Clear();phase++;if(phase>=phases.Count){Finish();return;}var p=phases[phase];for(int i=0;i<p.count;i++){var g=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/PixelFX/LightningNova/Prefabs/LightningNova_"+p.variant+".prefab"));g.name="Performance_"+i;g.transform.position=new Vector3(0,-.35f,0);if(p.variant=="3D")g.transform.rotation=Quaternion.Euler(30,-22,0);clones.Add(g);foreach(var ps in g.GetComponentsInChildren<ParticleSystem>()){ps.Stop(false,ParticleSystemStopBehavior.StopEmittingAndClear);var m=ps.main;m.duration=1.9f;m.loop=true;m.startDelay=p.stagger?i*1.9f/p.count:0;ps.useAutoRandomSeed=false;ps.randomSeed=(uint)(69+i*17);ps.Play(false);}}
  systems=clones.SelectMany(g=>g.GetComponentsInChildren<ParticleSystem>()).ToArray();begin=Time.timeAsDouble;File.WriteAllText(Path.Combine(Out,"PerformanceProgress.json"),JsonConvert.SerializeObject(new{phase,total=phases.Count,variant=p.variant,p.count,p.stagger,p.repeat}));}
 static object Stats(IEnumerable<double> data){var a=data.Where(x=>!double.IsNaN(x)&&!double.IsInfinity(x)).OrderBy(x=>x).ToArray();if(a.Length==0)return new{available=false};return new{count=a.Length,median=a[a.Length/2],p95=a[(int)((a.Length-1)*.95)],max=a[a.Length-1]};}
 static void Finish(string error=null){EditorApplication.update-=Tick;foreach(var g in clones)if(g!=null)UnityEngine.Object.Destroy(g);for(int i=0;i<demos.Count;i++)if(demos[i]!=null)demos[i].SetActive(active[i]);Application.runInBackground=background;foreach(var r in counters.Values)r.Dispose();if(focused!=null)focused.Focus();
  File.WriteAllText(Path.Combine(Out,"PerformanceRaw.json"),JsonConvert.SerializeObject(new{environment,phases,rows},Formatting.Indented));var groups=rows.GroupBy(r=>new{phases[r.phase].variant,phases[r.phase].count,phases[r.phase].stagger}).Select(g=>new{variant=g.Key.variant,instances=g.Key.count,g.Key.stagger,frames=g.Count(),batches=Stats(g.Select(r=>(double)r.batches)),draws=Stats(g.Select(r=>(double)r.draws)),setPass=Stats(g.Select(r=>(double)r.setPass)),mainMs=Stats(g.Select(r=>r.cpu)),renderMs=Stats(g.Select(r=>r.render)),gpuMs=Stats(g.Select(r=>r.gpu)),particleMs=Stats(g.Select(r=>r.particle)),gcBytes=Stats(g.Select(r=>r.gc)),particles=Stats(g.Select(r=>(double)r.particles))}).ToArray();
  File.WriteAllText(Path.Combine(Out,"PerformanceSummary.json"),JsonConvert.SerializeObject(new{success=error==null,error,environment,method="Real Play Mode; 0/1/8/32 overlapping synchronous instances + 8 staggered 3D; two repetitions; 1.7 seconds warmup / 3.3 seconds sampling per phase; every second engine frame; no captures/FrameDebugger during timing. Whole-frame Editor costs include UI and probe. Unknown business budget: exploratory only.",counters=counters.Keys,groups,restored=true,pending=new[]{"Target Player/device budget and shader variants","Per-pass GPU/overdraw","Exact batch merge/break reasons","Long-run pooled memory"}},Formatting.Indented));}
 static void Tick(){try{if(!Application.isPlaying){Finish("Stopped externally");return;}if(frame==Time.frameCount||Time.frameCount%2!=0)return;frame=Time.frameCount;double age=Time.timeAsDouble-begin;if(age>=5){Next();return;}if(age<1.7)return;rows.Add(new Row{phase=phase,frame=frame,age=age,batches=UnityStats.batches,draws=UnityStats.drawCalls,setPass=UnityStats.setPassCalls,particles=systems.Sum(p=>p.particleCount),cpu=Read("CPU Main Thread Frame Time"),render=Read("CPU Render Thread Frame Time"),gpu=Read("GPU Frame Time"),particle=Read("ParticleSystem.Update"),gc=Read("GC Allocated In Frame",false)});}catch(Exception e){Finish(e.ToString());}}
 public static string Run(){if(!Application.isPlaying||Application.productName!="VFXDemo")throw new Exception("Wrong state");background=Application.runInBackground;Application.runInBackground=true;focused=EditorWindow.focusedWindow;var gameType=typeof(Editor).Assembly.GetType("UnityEditor.GameView");EditorWindow.GetWindow(gameType).Focus();
  foreach(var root in SceneManager.GetActiveScene().GetRootGameObjects().Where(g=>g.name=="LightningNova_2D_Demo"||g.name=="LightningNova_3D_Demo")){demos.Add(root);active.Add(root.activeSelf);root.SetActive(false);}
  var available=new List<ProfilerRecorderHandle>();ProfilerRecorderHandle.GetAvailable(available);foreach(var name in new[]{"CPU Main Thread Frame Time","CPU Render Thread Frame Time","GPU Frame Time","ParticleSystem.Update","GC Allocated In Frame"}){var found=available.FirstOrDefault(h=>ProfilerRecorderHandle.GetDescription(h).Name==name);if(found.Valid){var d=ProfilerRecorderHandle.GetDescription(found);counters[name]=ProfilerRecorder.StartNew(d.Category,name,1);}}
  environment=new{unity=Application.unityVersion,device=SystemInfo.graphicsDeviceName,api=SystemInfo.graphicsDeviceType.ToString(),editor=Application.isEditor,width=Camera.main.pixelWidth,height=Camera.main.pixelHeight,colorSpace=QualitySettings.activeColorSpace.ToString(),pipeline=GraphicsSettings.currentRenderPipeline.name,msaa=QualitySettings.antiAliasing,vSync=QualitySettings.vSyncCount,target=Application.targetFrameRate,hdr=Camera.main.allowHDR,ortho=Camera.main.orthographic,orthoSize=Camera.main.orthographicSize,cameraPosition=Camera.main.transform.position.ToString(),background=Camera.main.backgroundColor.ToString(),memoryAtStart=Profiler.GetTotalAllocatedMemoryLong()};
  for(int repeat=0;repeat<2;repeat++){phases.Add(new Phase{repeat=repeat,count=0,variant="none"});foreach(var count in new[]{1,8,32})foreach(var variant in new[]{"2D","3D"})phases.Add(new Phase{repeat=repeat,count=count,variant=variant});phases.Add(new Phase{repeat=repeat,count=8,variant="3D",stagger=true});}Next();EditorApplication.update+=Tick;return "Scheduled 16 phases (~80 seconds engine time); do not capture or run FrameDebugger until complete.";}
}
